from http import HTTPStatus

def get_user(uid, users):
    if uid <= 0:
        return HTTPStatus.BAD_REQUEST, {"error": "invalid id"}
    if uid not in users:
        return HTTPStatus.NOT_FOUND, {"error": "not found"}
    return HTTPStatus.OK, users[uid]

def create_user(name, users, next_id):
    users[next_id] = {"id": next_id, "name": name}
    return HTTPStatus.CREATED, users[next_id]

users = {1: {"id": 1, "name": "Ana"}}
for status, body in [get_user(1, users), get_user(0, users), get_user(9, users), create_user("Beto", users, 2)]:
    print(status.value, status.phrase, body)

